      tag_name: NEWER_STABLE_TAG,
      name: NEWER_STABLE_TAG,
      draft: false,
      prerelease: false,
      published_at: "2026-10-18T10:00:00Z",
      html_url: `https://github.com/mock/nexus/releases/${NEWER_STABLE_TAG}`,
      assets: [],
    },
    {
      tag_name: CURRENT_TAG,
      name: CURRENT_TAG,
      draft: false,
